def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my_ops = [h[0] for h in history]
    opp_ops = [h[1] for h in history]
    my_last, opp_last = history[-1]

    opp_c = opp_ops.count('C')
    opp_d = n - opp_c
    my_d = my_ops.count('D')
    opp_rate = opp_c / n

    # Consecutive opponent defections
    streak_opp_d = 0
    for i in range(n - 1, -1, -1):
        if opp_ops[i] == 'D':
            streak_opp_d += 1
        else:
            break

    # Consecutive mutual defections
    streak_dd = 0
    for i in range(n - 1, -1, -1):
        if my_ops[i] == 'D' and opp_ops[i] == 'D':
            streak_dd += 1
        else:
            break

    # Always defect on the final round
    if n == 99:
        return 'D'

    # Probe only after a long perfect cooperation, to exploit ALLC without hurting early probes
    if opp_d == 0 and my_d == 0 and n >= 40:
        return 'D'

    if opp_last == 'C':
        if my_last == 'D':
            # We defected and opponent still cooperated: keep exploiting
            return 'D'
        else:
            return 'C'

    # opp_last == 'D'
    if my_last == 'C':
        # Opponent defected unprovoked
        if streak_opp_d == 1 and opp_rate > 0.7:
            return 'C'
        # Forgive a long initial defection streak, but not if we just forgave last round
        if streak_opp_d >= 3 and opp_rate > 0.5:
            if n >= 2 and history[-2][0] == 'C' and history[-2][1] == 'D':
                return 'D'
            return 'C'
        return 'D'
    else:
        # Mutual defection
        if streak_dd >= 2 and opp_rate > 0.5:
            return 'C'
        return 'D'
